option.value:
body { 
    font-family: 'Geist Pixel Circle', 'Geist Pixel Square', 'Geist Pixel', monospace !important; 
    font-size: 85% !important; 
    line-height: 1.6 !important; 
    letter-spacing: 0.5px !important; 
} 

/* --- TEXTO RESALTADO (NEGRITAS) --- */
strong, b { 
    font-weight: normal !important; 
    color: #FF5D9E !important; 
    background: rgba(255, 93, 158, 0.1) !important; 
    padding: 2px 5px !important; 
    border-radius: 4px !important; 
} 

/* --- JERARQUÍA DE TÍTULOS ESTILO PRODUCTO TOP --- */

/* H1: Estilo Documentación de GitHub (Línea inferior limpia) */
h1 { 
    font-weight: normal !important;
    color: #00E5FF !important; 
    text-shadow: none !important;
    font-size: 1.45em !important; 
    margin-top: 1.5em !important; 
    margin-bottom: 0.6em !important; 
    border-bottom: 2px solid rgba(0, 229, 255, 0.2) !important; 
    padding-bottom: 0.3em !important;
} 

/* H2: Estilo Dashboard de Stripe (Barra de sección a la izquierda) */
h2 { 
    font-weight: normal !important;
    color: #00FF87 !important; 
    text-shadow: none !important;
    font-size: 1.25em !important; 
    margin-top: 1.4em !important; 
    margin-bottom: 0.5em !important; 
    border-left: 3px solid #00FF87 !important; /* Barra vertical verde */
    padding-left: 8px !important;
} 

/* H3: Prefijo de sub-sección automatizado */
h3 { 
    font-weight: normal !important;
    color: #00E5FF !important; 
    text-shadow: none !important;
    font-size: 1.10em !important; 
    margin-top: 1.2em !important; 
    margin-bottom: 0.4em !important; 
} 
h3::before {
    content: "## " !important; /* Prefijo estético discreto */
    color: rgba(0, 229, 255, 0.4) !important;
}

/* H4: Prefijo técnico automatizado */
h4 { 
    font-weight: normal !important;
    color: #00FF87 !important; 
    text-shadow: none !important;
    font-size: 0.95em !important; 
    margin-top: 1.1em !important; 
    margin-bottom: 0.4em !important; 
} 
h4::before {
    content: "◇ " !important; /* Inserta un rombo retro antes del título */
    color: rgba(0, 255, 135, 0.5) !important;
    margin-right: 4px !important;
}

/* H5: Formato Micro-Badge de Vercel/Linear (Mini etiqueta de estado) */
h5 {
    font-weight: normal !important;
    color: #E0E0E0 !important;
    text-shadow: none !important; 
    font-size: 0.75em !important;
    margin-top: 1.2em !important;
    margin-bottom: 0.4em !important;
    text-transform: uppercase !important; 
    letter-spacing: 1.5px !important;
    background: rgba(255, 255, 255, 0.08) !important; /* Caja de fondo contenedor */
    display: inline-block !important;
    padding: 2px 8px !important;
    border-radius: 3px !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
}

/* --- LISTAS --- */
ul { list-style-type: disc !important; } 
ul li::marker { color: #00E5FF !important; font-size: 1.1em !important; } 
ol li::marker { color: #FF5D9E !important; font-weight: normal !important; } 
li { padding-left: 5px !important; margin-bottom: 0.4em !important; }
